issues = {
    "Issue 1: Version reporting unreliability": {
        "file": "qutebrowser/utils/version.py",
        "problem": "ModuleInfo._initialize_info() never sets self._initialized = True",
        "impact": "Every call to get_version(), is_installed(), or is_outdated() re-runs initialization, causing inconsistent behavior with mocked modules",
        "fix": "Set self._initialized = True at the end of _initialize_info()"
    },
    "Issue 2: Blocklist download notification unreliability": {
        "file": "qutebrowser/components/utils/blockutils.py",
        "problem": "BlocklistDownloads.all_downloads_finished signal emits _done_count which only counts successful downloads, not total items processed",
        "impact": "The signal doesn't clearly indicate whether all items were processed, especially when some downloads fail",
        "fix": "Track total items processed separately and emit that count instead of just successful downloads"
    }
}

for issue, details in issues.items():
    print(f"\n{issue}")
    for key, value in details.items():
        print(f"  {key}: {value}")

